<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 尊重 packageManager 字段</span></span>
